require('./register-typescript.cjs');
const test = require('node:test');
const assert = require('node:assert/strict');
const awards = require('../lib/season-awards.ts');
const { buildLeagueRatings } = require('../lib/result-rebuild.ts');
const { buildMatchdayBalance, matchdayOptions } = require('../lib/matchday-balance.ts');
const { awardFixture } = require('./award-fixture.cjs');
const { awardViews } = require('./award-views.cjs');
// Captured from the pre-adoption Season Review, not generated by the code under test.
const expected = require('./award-golden.json');

test('MVP and Most Improved retain scores, eligibility, tie order and fallback rules in all 13 views', () => {
  const fixture = awardFixture();
  const replay = buildLeagueRatings(fixture);
  fixture.players = replay.players;
  fixture.history = replay.history.map((row,i) => ({...row,id:i+1}));
  const before = structuredClone(fixture);
  const model = buildMatchdayBalance(fixture.players,fixture.matches,'2027-01-01');
  const selected = fixture.players.filter(p => p.is_active === 1).slice(0,10);
  matchdayOptions(model,selected,[],[]);
  matchdayOptions(model,selected,[selected[0].id],[selected[1].id]);
  assert.deepEqual(awardViews(awards,fixture),expected);
  assert.deepEqual(fixture,before);
});

test('MVP points and qualification boundaries remain established competition rules', () => {
  assert.deepEqual([0,1,3,4,12,13,48].map(awards.minimumAwardMatches),[1,1,1,3,3,4,12]);
  assert.deepEqual([800,900,950,1000,1100,1200].map(awards.ratingPoints),[0,0,20,40,80,80]);
  assert.deepEqual(awards.awardScoreComponents({matches_played:6},1000,12),{rating:40,games:10,score:50});
});

test('uncertainty and team-model estimates cannot supply award points', () => {
  const fixture = awardFixture();
  const players = awards.playerSummariesForPeriod(fixture.players,fixture.matches,[],null,null,'all');
  const expectedRace = awards.mvpRace(players,fixture.matches).map(({key,value})=>({key,value}));
  const changed = players.map((player,i)=>({...player,strength:10000-i*1000,uncertainty:9000-i*800}));
  assert.deepEqual(awards.mvpRace(changed,fixture.matches).map(({key,value})=>({key,value})),expectedRace);
});
